from __future__ import annotations

import csv
import math
from datetime import date, datetime, timedelta
from pathlib import Path

import numpy as np

root = Path('/Users/doob/dev/energy_forecast_ws/94eee4/project/runs/94eee4')
source = root / 'opsd_de_load.csv'
out_path = root / 'forecast_jan_2020.csv'
cutoff = datetime.fromisoformat('2020-01-01 00:00:00+00:00')

hourly: dict[datetime, float] = {}
with source.open(newline='') as handle:
    for row in csv.DictReader(handle):
        timestamp = datetime.fromisoformat(row['utc_timestamp'])
        if timestamp < cutoff:
            hourly[timestamp] = float(row['DE_load_actual_entsoe_transparency'])

timezone = cutoff.tzinfo

def hourly_profile(day: date) -> np.ndarray:
    return np.array([
        hourly[datetime(day.year, day.month, day.day, hour, tzinfo=timezone)]
        for hour in range(24)
    ])

first_day = min(hourly).date()
last_day = max(hourly).date()
daily: dict[date, float] = {}
day = first_day
while day <= last_day:
    daily[day] = float(np.mean(hourly_profile(day)))
    day += timedelta(days=1)


def analog_date(target: date, analog_year: int) -> date:
    if target.day == 1:
        return date(analog_year, 1, 1)
    candidates = [
        date(analog_year, 1, day_number)
        for day_number in range(2, 15)
        if date(analog_year, 1, day_number).weekday() == target.weekday()
        and day_number != 6
    ]
    return min(candidates, key=lambda candidate: abs(candidate.day - target.day))


def analog_forecast(year: int) -> np.ndarray:
    values: list[float] = []
    for day_number in range(1, 8):
        target = date(year, 1, day_number)
        weighted_profiles: list[tuple[float, np.ndarray]] = []
        for age, weight in ((1, 1.0), (2, 0.7), (3, 0.49)):
            analog = analog_date(target, year - age)
            weighted_profiles.append((weight, hourly_profile(analog)))
        profile = sum(weight * values for weight, values in weighted_profiles) / sum(
            weight for weight, _ in weighted_profiles
        )
        values.extend(profile.tolist())
    return np.array(values)


def ridge_features(day: date) -> np.ndarray:
    values: list[float] = [1.0, daily[day - timedelta(days=364)]]
    for window in (7, 14, 28):
        values.append(float(np.mean([daily[day - timedelta(days=lag)] for lag in range(1, window + 1)])))
    values.extend(float(day.weekday() == weekday) for weekday in range(7))
    days_in_year = 366 if date(day.year, 12, 31).timetuple().tm_yday == 366 else 365
    year_fraction = (day - date(day.year, 1, 1)).days / days_in_year
    for harmonic in range(1, 9):
        angle = 2 * math.pi * harmonic * year_fraction
        values.extend((math.sin(angle), math.cos(angle)))
    trend = (day - date(2015, 1, 1)).days / 365.25
    values.extend((trend, trend * trend))
    special_dates = [(12, day_number) for day_number in range(20, 32)] + [
        (1, day_number) for day_number in range(1, 15)
    ]
    values.extend(float((day.month, day.day) == special) for special in special_dates)
    return np.array(values)


def ridge_daily_means(year: int) -> np.ndarray:
    training_start = date(year - 2, 1, 1)
    training_end = date(year, 1, 1)
    rows: list[tuple[np.ndarray, float]] = []
    day = training_start
    while day < training_end:
        features = ridge_features(day)
        if np.all(np.isfinite(features)):
            rows.append((features, daily[day]))
        day += timedelta(days=1)

    design = np.stack([features for features, _ in rows])
    targets = np.array([target for _, target in rows])
    means = design[:, 1:].mean(axis=0)
    scales = design[:, 1:].std(axis=0)
    scales[scales < 1e-9] = 1.0
    standardized = np.column_stack([
        np.ones(len(design)),
        (design[:, 1:] - means) / scales,
    ])
    penalty = np.eye(standardized.shape[1])
    penalty[0, 0] = 0.0
    coefficients = np.linalg.solve(
        standardized.T @ standardized + 100.0 * penalty,
        standardized.T @ targets,
    )

    predictions: list[float] = []
    for day_number in range(1, 8):
        features = ridge_features(date(year, 1, day_number))
        standardized_features = np.concatenate((
            np.array([1.0]),
            (features[1:] - means) / scales,
        ))
        predictions.append(float(standardized_features @ coefficients))
    return np.array(predictions)


def ridge_hourly_forecast(year: int) -> np.ndarray:
    values: list[float] = []
    for day_number, daily_mean in enumerate(ridge_daily_means(year), start=1):
        target = date(year, 1, day_number)
        profile = hourly_profile(analog_date(target, year - 1))
        normalized_profile = profile / np.mean(profile)
        values.extend((daily_mean * normalized_profile).tolist())
    return np.array(values)

forecast = 0.6 * analog_forecast(2020) + 0.4 * ridge_hourly_forecast(2020)
